"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

export const EASE_OUT: [number, number, number, number] = [0.22, 1, 0.36, 1];

/**
 * Scroll-triggered entrance (framer-motion style): fades + slides up once
 * when the element enters the viewport. Falls back to a plain div when the
 * user prefers reduced motion.
 */
export function Reveal({
  children,
  className,
  delay = 0,
  y = 24,
  amount = 0.25,
}: {
  children?: ReactNode;
  className?: string;
  delay?: number;
  y?: number;
  amount?: number;
}) {
  const reduced = useReducedMotion();

  if (reduced) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount }}
      transition={{ duration: 0.7, ease: EASE_OUT, delay }}
    >
      {children}
    </motion.div>
  );
}

/** 1px rule that "draws" itself from left to right when scrolled into view. */
export function DrawRule({ className = "" }: { className?: string }) {
  const reduced = useReducedMotion();

  if (reduced) {
    return <div aria-hidden className={className} />;
  }

  return (
    <motion.div
      aria-hidden
      className={className}
      initial={{ scaleX: 0 }}
      whileInView={{ scaleX: 1 }}
      viewport={{ once: true, amount: 1 }}
      transition={{ duration: 0.9, ease: EASE_OUT, delay: 0.15 }}
      style={{ transformOrigin: "left center" }}
    />
  );
}
